<?php
require_once __DIR__.'/../config/bootstrap.php';require_admin();
$period=current_period($pdo);$periodId=(int)($period['id']??0);
function admin_rank(PDO $pdo,int $pid,string $cat):array{$q=$pdo->prepare("SELECT k.nomor_peserta,k.nama,COUNT(v.id) total_suara FROM kontestan k LEFT JOIN voting v ON v.kontestan_id=k.id AND v.periode_id=? WHERE k.kategori=? GROUP BY k.id ORDER BY total_suara DESC,k.nomor_peserta");$q->execute([$pid,$cat]);return $q->fetchAll();}
$k=admin_rank($pdo,$periodId,'Kakang');$s=admin_rank($pdo,$periodId,'Senduk');$labels=array_merge(array_map(fn($x)=>'K '.$x['nomor_peserta'],$k),array_map(fn($x)=>'S '.$x['nomor_peserta'],$s));$values=array_merge(array_map(fn($x)=>(int)$x['total_suara'],$k),array_map(fn($x)=>(int)$x['total_suara'],$s));
$page_title='Hasil Voting';require __DIR__.'/../includes/header.php';
?>
<header class="page-head"><div class="container"><span class="eyebrow">Administrator</span><h1 class="mt-2">Hasil dan Klasemen</h1><p><?=e($period['nama_periode']??'Belum ada periode')?></p></div></header><section class="section-pad"><div class="container"><div class="panel-card mb-4"><h4 class="fw-bold">Grafik Perolehan Suara</h4><canvas id="voteChart" height="100"></canvas></div><div class="row g-4"><div class="col-lg-6"><div class="panel-card"><h4 class="fw-bold mb-3">Kakang</h4><div class="table-responsive"><table class="table"><thead><tr><th>Rank</th><th>Kontestan</th><th>Suara</th></tr></thead><tbody><?php foreach($k as $i=>$r):?><tr><td><?=$i+1?></td><td><?=e($r['nomor_peserta'].' · '.$r['nama'])?></td><td class="fw-bold"><?=$r['total_suara']?></td></tr><?php endforeach;?></tbody></table></div></div></div><div class="col-lg-6"><div class="panel-card"><h4 class="fw-bold mb-3">Senduk</h4><div class="table-responsive"><table class="table"><thead><tr><th>Rank</th><th>Kontestan</th><th>Suara</th></tr></thead><tbody><?php foreach($s as $i=>$r):?><tr><td><?=$i+1?></td><td><?=e($r['nomor_peserta'].' · '.$r['nama'])?></td><td class="fw-bold"><?=$r['total_suara']?></td></tr><?php endforeach;?></tbody></table></div></div></div></div><div class="small-muted mt-4">Jumlah suara dihitung langsung dari tabel voting. Kategori Kakang dan Senduk dipisahkan.</div></div></section>
<script src="https://cdn.jsdelivr.net/npm/chart.js"></script><script>
const chartCanvas=document.getElementById('voteChart');
new Chart(chartCanvas,{type:'bar',data:{labels:<?=json_encode($labels,JSON_UNESCAPED_UNICODE)?>,datasets:[{label:'Jumlah suara',data:<?=json_encode($values)?>,backgroundColor:['#b51f2b','#123d32','#087f83','#ffd43b','#6c757d','#c56f3a']}]},options:{responsive:true,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,ticks:{precision:0}}}}});
</script>
<?php require __DIR__.'/../includes/footer.php';?>
